package net.civeira.phylax.features.access.userinvitation.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.user.domain.UserReference;

class InvitedByVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property invited by of user invitation ")
  void test_invited_by_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", InvitedByVO.fromReference("10").getInvitedByUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", InvitedByVO.tryFromReference("11").getInvitedByUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", InvitedByVO.tryFromReference("12", fails).getInvitedByUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> InvitedByVO.tryFrom(null));
    Assertions.assertEquals(UserReference.of("one"),
        InvitedByVO.from(UserReference.of("one")).getInvitedBy());
    Assertions.assertThrows(ConstraintException.class, () -> InvitedByVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + UserReference.of("one") + "]",
        InvitedByVO.from(UserReference.of("one")).toString());
  }
}
